widget.solution:
def minutes_between(t1, t2):
    h1, m1 = map(int, t1.split(':'))
    h2, m2 = map(int, t2.split(':'))
    return (h2 * 60 + m2 - h1 * 60 - m1) % (24 * 60)


def simple_interest(principal, rate, months):
    return principal * rate / 100 * months / 12
